vec3 rgb2hsl(vec3 rgb)
{
    float vmax = max(max(rgb.r, rgb.g), rgb.b);
    float vmin = min(min(rgb.r, rgb.g), rgb.b);
    float l = (vmax + vmin) / 2.0;

    if (vmax == vmin) return vec3(0.0, 0.0, l);

    float d = vmax - vmin;
    float s = l > 0.5 ? d / (2.0 - vmax - vmin) : d / (vmax + vmin);
    float h;
    if (vmax == rgb.r) h = (rgb.g - rgb.b) / d + (rgb.g < rgb.b ? 6.0 : 0.0);
    if (vmax == rgb.g) h = (rgb.b - rgb.r) / d + 2.0;
    if (vmax == rgb.b) h = (rgb.r - rgb.g) / d + 4.0;
    h /= 6.0;
    return vec3(h, s, l);
}

float hue2rgb(float p, float q, float t)
{
    if (t < 0.0) t += 1.0;
    if (t > 1.0) t -= 1.0;
    if (t < 1.0/6.0) return p + (q - p) * 6.0 * t;
    if (t < 1.0/2.0) return q;
    if (t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
    return p;
}
vec3 hsl2rgb(vec3 hsl)
{
    if (hsl.y == 0.0) return hsl.zzz;

    float q = hsl.z < 0.5 ? hsl.z * (1.0 + hsl.y) : hsl.z + hsl.y - hsl.z * hsl.y;
    float p = 2.0 * hsl.z - q;
    return vec3(
        hue2rgb(p, q, hsl.x + 1.0/3.0),
        hue2rgb(p, q, hsl.x),
        hue2rgb(p, q, hsl.x - 1.0/3.0)
    );
}

vec3 mix3(vec3 a, vec3 b, vec3 t)
{
    return vec3(
        mix(a.x, b.x, t.x),
        mix(a.y, b.y, t.y),
        mix(a.z, b.z, t.z)
    );
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    float chtimeshift = 1.0;

    float t = sin(iTime);
    vec3 t3 = sin(iTime + vec3(-chtimeshift, 0, chtimeshift));

    vec2 dsplc = vec2(1.0);
    //dsplc = vec2(t / 2.0, 0.0);

    vec2 uv = fragCoord / iResolution.xy;

    vec3 rgb1 = texture(iChannel0, uv - dsplc).rgb;
    vec3 rgb2 = texture(iChannel1, uv + dsplc).rgb;

    vec3 hsl1 = rgb2hsl(rgb1);
    vec3 hsl2 = rgb2hsl(rgb2);

    vec3 trns = hsl2rgb(  mix3( hsl1, hsl2, t3 )  );

    fragColor = vec4(trns, 1.0);
}
